    c0 = min(c for r, c in pts); c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]
    # Complete the outer rectangular contour, marking missing cells in color 2.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] == bg:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
